(window.WCD=window.WCD||[]).push(["drag",[["Q64157495",1,"queen","A'Keria C. Davenport","C","Gregory D'Wayne, plus connu sous le nom de scène A'Keria C. Davenport, né le 1er mars 1988 à Dallas, au Texas, est une drag queen américaine principalement connue pour sa participation à la onzième saison de RuPaul's Drag Race et aux sixième et onzième saisons de RuPaul's Drag Race All Stars.","Gregory D'Wayne, plus connu sous le nom de scène A'Keria C.","fr:A'Keria_C._Davenport","c:6/61/Dragcon2-SAT-147_%2847937164867%29_%28cropped%29.jpg"],["Q5798973",2,"queen","Adore Delano","R","Adore Delano, est une drag queen et chanteuse américaine. Elle apparaît pour la première fois à la télévision dans la saison 7 de American Idol en 2008. Elle finit par la suite dans le top trois de la sixième saison de RuPaul's Drag Race, et sort dans la foulée son premier album Till Death Do Us Party en 2014.","Adore Delano, est une drag queen et chanteuse américaine.","fr:Adore_Delano","c:f/f5/Adore_Delano.jpg"],["Q16029552",3,"queen","Alaska Thunderfuck","E","Alaska Thunderfuck 5000, aussi connu sous le nom d'Alaska Thunderfuck ou Alaska Thunderfvck, ou Alaska 5000, est le nom de scène de Justin Honard, une drag queen connue pour sa participation à l'émission de télévision RuPaul's Drag Race.",119,"fr:Alaska_Thunderfuck","c:8/8a/Dragcon2-SAT-33_%2847937192816%29_%28cropped%29.jpg"],["Q16201417",4,"queen","Alyssa Edwards","R","Justin Dwayne Lee Johnson, plus connu sous le nom de scène Alyssa Edwards, est une drag queen américaine, principalement connue pour sa participation à la cinquième saison de RuPaul's Drag Race, la deuxième saison de RuPaul's Drag Race All Stars et la première saison de RuPaul's Drag Race: Global All Stars.",105,"fr:Alyssa_Edwards","c:c/c6/Peppermint_and_Alyssa_Edwards_at_Dragcon_by_dvsross_%28cropped%29.jpg"],["Q116092287",5,"queen","Anetra","C","Anetra est une drag queen américaine, finaliste de la 15e saison de RuPaul's Drag Race, célèbre pour son entrée « The Duck » et ses talents d'arts martiaux.",113,"en:Anetra","c:4/4e/Anetra_%28cropped%29.jpg"],["Q111583889",6,"queen","Angeria Paris VanMicheals","C","Tommie Laron Holsey, plus connu sous le nom de scène Angeria Paris VanMicheals, est une drag queen américaine principalement connue pour sa participation à la quatorzième saison de RuPaul's Drag Race et à la neuvième saison de RuPaul's Drag Race All Stars.",109,"fr:Angeria_Paris_VanMicheals","c:6/64/DragCon_2023_%40_DVSROSS_Photgraphy_-130_%28cropped%29.jpg"],["Q55262328",7,"queen","Aquaria","PC","Giovanni Palandrani, plus connu sous le nom de scène Aquaria, est une drag queen américaine principalement connue pour sa participation à la dixième saison de RuPaul's Drag Race.",118,"fr:Aquaria_(drag_queen)","c:d/d3/RuPaul_DragCon_2022_%2852072217807%29_%28cropped%29.jpg"],["Q74514336",8,"queen","Baga Chipz","PC","Baga Chipz est une drag queen anglaise à l'humour franc, révélée par la première saison de RuPaul's Drag Race UK en 2019.",115,"en:Baga_Chipz","c:2/27/DragCon_2023_%40_DVSROSS_Photgraphy_-51_%28cropped%29.jpg"],["Q4875441",9,"queen","BeBe Zahara Benet","C","Nea Marshall Nudi Ngwa, plus connue sous le nom de scène BeBe Zahara Benet, est une drag queen camerouno-américaine principalement connue pour avoir gagné la première saison de RuPaul's Drag Race en 2009. En 2018, elle est la candidate secrète de la troisième saison de RuPaul's Drag Race: All Stars, où elle finit troisième.",115,"fr:BeBe_Zahara_Benet","c:3/37/Bebe_Zahara_Benet_at_NUBIA_2020_%28cropped%29.jpg"],["Q16226036",10,"queen","Bianca Del Rio","E","Roy Haylock, né le 27 juin 1975 à La Nouvelle-Orléans en Louisiane, plus connu sous son nom de scène Bianca Del Rio, est un acteur, humoriste, et drag queen américain. Drag queen réputée des clubs de La Nouvelle-Orléans et de New York, où il collabore souvent avec Lady Bunny, il est également connu pour avoir remporté la sixième saison de RuPaul's Drag Race.",116,"fr:Bianca_Del_Rio","c:3/34/Close-up_Bianca_Del_Rio%2C_Rolodex_of_Hate_Tour%2C_Theater_Amsterdam_2015.jpg"],["Q104841683",11,"queen","Bimini Bon Boulash","R","Tommy Hibbitts, plus connu.e sous le nom de scène Bimini Bon Boulash ou plus simplement Bimini, est une drag queen britannique, principalement connue pour sa participation à la deuxième saison de RuPaul's Drag Race UK.",114,"fr:Bimini_Bon_Boulash","c:a/a9/Bimini_Bon-Boulash_%28cropped%29.png"],["Q54357977",12,"queen","Blair St. Clair","C","Blair St. Clair, née le 16 mai 1995, est une drag queen et chanteuse américaine, plus connue pour avoir participé à la dixième saison de la compétition télévisée RuPaul's Drag Race et aussi à la cinquième saison de Rupaul's Drag Race All Star.","Blair St.","fr:Blair_St._Clair","c:5/5e/Rupaul_Dragcon_2018-146_%2841356433254%29.jpg"],["Q24287374",13,"queen","Bob the Drag Queen","R","Christopher Delmar Caldwell, plus connu sous ses noms de scène Caldwell Tidicue et Bob the Drag Queen, est un artiste américain principalement connu pour sa participation à la huitième saison de RuPaul's Drag Race.",117,"fr:Bob_the_Drag_Queen","c:5/51/Madonna_-_The_Celebration_tour_live_-_London_15_10_2023_%2853272568285%29_%28cropped%29.jpg"],["Q110625344",14,"queen","Bosco (drag queen)","PC","Blair Constantino, plus connue sous le nom de scène Bosco, est une drag queen et actrice de théâtre américaine, principalement connue pour sa participation à la quatorzième saison de RuPaul's Drag Race, où elle termine en finaliste, et la dixième saison de RuPaul's Drag Race: All Stars, où elle termine finaliste également.",111,"fr:Bosco_(drag_queen)","c:f/fe/DragCon_2022-128_%2852075781895%29_%28cropped%29.jpg"],["Q63565748",15,"queen","Brooke Lynn Hytes","PC","Brock Hayhoe, plus connu sous le nom de scène Brooke Lynn Hytes, est une drag queen et personnalité télévisée canadienne, danseur classique et artiste principalement connue pour avoir participé à la onzième saison de RuPaul's Drag Race et comme présentatrice de la compétition de télé-réalité Canada's Drag Race.",109,"fr:Brooke_Lynn_Hytes","c:d/dd/Dragcon2-SAT-60_%2847937185348%29.jpg"],["Q5043441",16,"queen","Carmen Carrera","PC","Carmen Carrera, née le 13 avril 1985 à Elmwood Park, est une personnalité de la téléréalité, modèle, artiste burlesque et actrice américaine, connue pour son apparition dans la troisième saison de RuPaul's Drag Race, ainsi que pour dans sa série dérivée Drag U.",118,"fr:Carmen_Carrera","c:2/28/Carmen_Carrera.jpg"],["Q16201535",17,"queen","Chad Michaels","C","Chad Michaels est une drag queen américaine connue pour être sosie de la chanteuse Cher, ainsi que finaliste de la saison 4 de RuPaul's Drag Race et gagnante de la première saison de RuPaul's Drag Race All Stars.",114,"fr:Chad_Michaels","c:1/10/Chad_Michaels_as_Cher.jpg"],["Q5178572",18,"queen","Courtney Act","R","Shane Jenek est une drag queen et un chanteur australien. En tant que Courtney Act, Jenek termine en demi-finale de Australian Idol en 2003 et devient le troisième chanteur de la compétition à sortir un single solo officiel, après Guy Sebastian et Shannon Noll. Le single Rub Me Wrong sort en 2004, et se classe à la vingt-neuvième position de l'ARIA Singles Chart. Act participe également à la sixième saison de RuPaul's Drag Race où elle échoue en finale avec Adore Delano contre Bianca Del Rio.","Shane Jenek est une drag queen et un chanteur australien.","fr:Courtney_Act","c:5/51/Courtney_Act_2017_MTV_International.png"],["Q96180066",19,"queen","Crystal Methyd","PC","Cody D. Harness, plus connu sous le nom de scène Crystal Methyd, est une drag queen américaine principalement connue pour sa participation à la douzième saison de RuPaul's Drag Race et à la onzième saison de RuPaul's Drag Race All Stars.","Cody D.","fr:Crystal_Methyd","c:a/a5/Crystal_Methyd_DragCon2024_%40DVSROSS_%281%29_%28cropped%29.jpg"],["Q114267690",20,"queen","Danny Beard","R","Danny Beard est un artiste drag et chanteur britannique, vainqueur de la quatrième saison de RuPaul's Drag Race UK.",null,"en:Danny_Beard","c:6/6b/Eurovision_Song_Contest_2023_-_Eurovision_Village_-_Danny_Beard_-_52902352686_%28cropped%29.jpg"],["Q105883647",21,"queen","Denali (drag queen)","C","Cordero Zuckerman, plus connu sous le nom de scène Denali Foxx ou plus simplement Denali, est un chorégraphe, drag queen et patineur artistique américain principalement connu pour sa participation à la treizième saison de RuPaul's Drag Race.",114,"fr:Denali_(drag_queen)","c:9/90/RuPaul_DragCon_2022_%2852073262148%29.jpg"],["Q16204776",22,"queen","Detox Icunt","C","Deandra Sanderson, plus connue sous le nom de scène Detox Icunt ou plus simplement Detox, est une drag queen et artiste américaine.",119,"fr:Detox_Icunt","c:6/63/Dragcon2-SAT-138_%2847937165387%29.jpg"],["Q99342660",23,"queen","Envy Peru","C","Envy Peru est une drag queen péruvienne et néerlandaise, gagnante de la première saison de Drag Race Holland.",null,"en:Envy_Peru","c:e/ed/2022-09-13-Envy_Peru_Deutscher_Fernsehpreis_2022-0467.jpg"],["Q53567345",24,"queen","Eureka O'Hara","C","David Huggard, plus connu sous le nom de scène Eureka! ou précédemment Eureka O'Hara, est une drag queen américaine principalement connue pour sa participation à la neuvième saison et à la dixième saison de RuPaul's Drag Race ainsi qu'à la sixième saison de RuPaul's Drag Race All Stars.","David Huggard, plus connu sous le nom de scène Eureka!","fr:Eureka_O'Hara","c:1/14/Eureka_july2018_%28cropped2%29.jpg"],["Q95995934",25,"queen","Gigi Goode","PC","Gigi Geggie, plus connue sous le nom de scène Gigi Goode, est une drag queen américaine principalement connue pour avoir participé à la douzième saison de RuPaul's Drag Race.",114,"fr:Gigi_Goode","c:4/41/RuPaul_DragCon_2022_%2852073260946%29.jpg"],["Q21290291",26,"queen","Ginger Minj","R","Joshua Allan Eads, plus connu sous le nom de scène Ginger Minj, est un acteur, chanteur et drag queen américain, principalement connu pour avoir participé à la septième saison de RuPaul's Drag Race, ainsi qu'à la deuxième et à la sixième saison de RuPaul's Drag Race All Stars. En 2025 elle gagne la Saison 10 de RuPaul's Drag Race All Stars.",112,"fr:Ginger_Minj","c:b/b1/Rupaul_Dragcon_2018-187_%2841356426934%29.jpg"],["Q30933614",27,"queen","Gloria Groove","PC","Gloria Groove est une drag queen, chanteuse et rappeuse brésilienne, l'une des artistes pop les plus populaires du Brésil.",114,"en:Gloria_Groove","c:b/b3/10_230624_-_Bruno_Figueiredo_-_SENSA_-_275_%2853011340565%29.jpg"],["Q105580864",28,"queen","Gottmik","R","Kade Gottlieb, plus connu sous le nom de scène Gottmik, est un artiste, drag queen et maquilleur américain principalement connu pour sa participation à la treizième saison de RuPaul's Drag Race.",106,"fr:Gottmik","c:0/0f/RuPaul_DragCon_2022_%2852073262398%29.jpg"],["Q111531803",29,"queen","Grag Queen","C","Grag Queen est une chanteuse et drag queen brésilienne, gagnante de la première saison du concours Queen of the Universe.",111,"en:Grag_Queen","c:8/89/DragCon_2024_%40_DVSROSS_Photgraphy_-59_%28cropped%29.jpg"],["Q95684565",30,"queen","Heidi N Closet","C","Trevien Anthonie Cheek, plus connu sous le nom de scène Heidi N Closet, est une drag queen américaine principalement connue pour sa participation à la douzième saison de RuPaul's Drag Race et à la huitième saison de RuPaul's Drag Race All Stars.",116,"fr:Heidi_N_Closet","c:f/f5/RuPaul_DragCon_2022_%2852072213147%29_%28cropped_-_Heidi_N_Closet%29.jpg"],["Q95684633",31,"queen","Jaida Essence Hall","C","Jared Johnson, plus connu sous le nom de scène Jaida Essence Hall, est un costumier, maquilleur et drag queen américain, principalement connu pour avoir gagné la douzième saison de RuPaul's Drag Race.",109,"fr:Jaida_Essence_Hall","c:1/1c/Luck_Be_a_Lady-Treasure_Island_Casino_Welsh%2C_MN-Flip_Phone_Events.jpg"],["Q104844641",32,"queen","Jimbo (drag queen)","C","James Insell, plus connu sous le nom de scène Jimbo, est une drag queen canadienne principalement connue pour sa participation à la première saison de Canada's Drag Race, la première saison de RuPaul's Drag Race: UK vs The World et la huitième saison de RuPaul's Drag Race All Stars.",112,"fr:Jimbo_(drag_queen)","c:c/c2/DragCon_2023_%40_DVSROSS_Photgraphy_-34_%28cropped%29.jpg"],["Q16070640",33,"queen","Jinkx Monsoon","E","Jinkx Monsoon est le nom de scène de Hera Hoffer, drag queen et gagnante de la cinquième saison de RuPaul's Drag Race et de la septième saison de RuPaul's Drag Race: All Stars.",117,"fr:Jinkx_Monsoon","c:4/4c/Jinkx_Monsoon_006_-_DC_Capital_Pride_street_festival_-_2013-06-09_%289001924615%29.jpg"],["Q110588591",34,"queen","Jorgeous","C","Jorge Meza, plus connu sous le nom de scène Jorgeous, est une drag queen américaine principalement connue pour sa participation à la quatorzième saison de RuPaul's Drag Race et aux neuvième et dixième saisons de RuPaul's Drag Race All Stars.",113,"fr:Jorgeous","c:0/04/Jorgeous_performing_with_Werq_the_World_2025_at_Caesars_Windsor%2C_Windsor%2C_Ontario%2C_2025-08-22_02.jpg"],["Q16201479",35,"queen","Jujubee","R","Jujubee est une drag queen américaine originaire de Lowell, révélée par la saison 2 de RuPaul's Drag Race et devenue l'une des favorites des All Stars.",116,"en:Jujubee","c:1/19/RuPaul_DragCon_2022_%2852072217127%29.jpg"],["Q105811172",36,"queen","Kandy Muse","C","Kandy Muse est une drag queen new-yorkaise, finaliste de la saison 13 de RuPaul's Drag Race.",null,"en:Kandy_Muse","c:a/a9/RuPaul_DragCon_2022_%2852073487739%29_%28cropped_-_Kandy_Muse%29.jpg"],["Q21592158",37,"queen","Katya Zamolodchikova","E","Brian Joseph McCook, plus connu sous le nom de scène Yekaterina Petrovna Zamolodchikova, souvent abrégé en Katya, est une drag queen américaine. Elle est principalement connue pour avoir participé à la septième saison de RuPaul's Drag Race et à la deuxième saison de RuPaul's Drag Race: All Stars, ainsi que comme animatrice de la web-série UNHhhh, accompagnée de Trixie Mattel.",117,"fr:Katya_Zamolodchikova","c:c/cc/Me_with_Katya_Zamolodchikova_%28cropped2%29.jpg"],["Q21290334",38,"queen","Kennedy Davenport","C","Reuben Asberry Jr., plus connu sous le nom de scène Kennedy Davenport, est une drag queen américaine. Elle est principalement connue pour avoir participé à la septième saison de RuPaul's Drag Race, où elle arrive quatrième, et à la troisième saison de RuPaul's Drag Race: All Stars, où elle se place seconde mais aussi à la deuxième saison de Canada's Drag Race: Canada vs The World.","Reuben Asberry Jr., plus connu sous le nom de scène Kennedy Davenport, est une drag queen américaine.","fr:Kennedy_Davenport","c:6/67/Kennedy_Davenport_at_LA_Drag_Con_2022_by_dvsross.jpg"],["Q30248894",39,"queen","Kim Chi","PC","Sang-Young Shin, plus connue sous le nom de scène Kim Chi, est une drag queen, artiste et personnalité télévisée coréano-américaine, principalement connue pour avoir participé à la huitième saison de RuPaul's Drag Race. Kim est la première participante coréano-américaine de l'émission, mais également la première drag queen coréano-américaine à apparaître à la télévision américaine.",112,"fr:Kim_Chi_(drag_queen)","c:8/81/Rupaul_Dragcon_2018-80_%2841175951055%29.jpg"],["Q110124197",40,"queen","Krystal Versace","C","Luke Fenn, plus connu sous le nom de scène Krystal Versace, est une drag queen anglaise principalement connue pour avoir participé à la troisième saison de RuPaul's Drag Race UK.",114,"fr:Krystal_Versace","c:5/5f/DragCon_2023_%40_DVSROSS_Photgraphy_-18_%28cropped%29.jpg"],["Q59555263",41,"queen","Kylie Sonique Love","C","Kylie Sonique Love, anciennement connue sous le nom de scène Sonique, est une chanteuse, danseuse, drag queen, personnalité télévisée et activiste américaine, principalement connue pour sa participation à la deuxième saison de RuPaul's Drag Race et à la sixième saison de RuPaul's Drag Race All Stars.",110,"fr:Kylie_Sonique_Love","c:9/9f/RuPaul_DragCon_2022_%2852073489984%29.jpg"],["Q111623391",42,"queen","Lady Camden","C","Lady Camden est une drag queen et danseuse britannique installée aux États-Unis, finaliste de la saison 14 de RuPaul's Drag Race.",109,"en:Lady_Camden","c:b/b0/DragCon_2023_%40_DVSROSS_Photgraphy_-104_%28cropped%29.jpg"],["Q16728868",43,"queen","Laganja Estranja","PC","Jay Evan Jackson, connue professionnellement sous le nom de Laganja Estranja, née le 28 décembre 1988, est une chorégraphe et drag queen américaine basée à Los Angeles. Laganja est une participante de la sixième saison de RuPaul's Drag Race, terminant à la huitième place. Elle fait son coming-out transgenre en 2021.",110,"fr:Laganja_Estranja","c:4/4c/DragCon_2023_%40_DVSROSS_Photgraphy_-65.jpg"],["Q18713435",44,"queen","Latrice Royale","PC","Timothy Wilcots, plus connu sous le nom de scène Latrice Royale, est une drag queen américaine, principalement connu pour son apparition dans la quatrième saison de RuPaul's Drag Race, où elle obtient le titre de Miss Congeniality, ainsi que dans la première et la quatrième saison de RuPaul's Drag Race: All Stars.",116,"fr:Latrice_Royale","c:5/5f/RuPaul_DragCon_2022_%2852073258068%29.jpg"],["Q105003185",45,"queen","Lawrence Chaney","PC","Lawrence Chaney est une drag queen écossaise de Glasgow, gagnante de la deuxième saison de RuPaul's Drag Race UK.",null,"en:Lawrence_Chaney","c:8/84/DragCon_2023_%40_DVSROSS_Photgraphy_-16_%28cropped%29.jpg"],["Q6749693",46,"queen","Manila Luzon","PC","Karl Philip Michael Westerberg, plus connu sous le nom de scène Manila Luzon, est une drag queen, artiste et personnalité télévisée américaine. Elle est principalement connue pour avoir participé à la troisième saison de RuPaul's Drag Race, où elle se place deuxième, ainsi qu'aux première et quatrième saisons de RuPaul's Drag Race: All Stars. Son nom est un jeu de mots avec les noms anglais de la capitale, Manille, et de la plus grande île des Philippines, pays de naissance de sa mère.",108,"fr:Manila_Luzon","c:c/c0/Dragcon-4_%2847937164822%29.jpg"],["Q48720235",47,"queen","Milk (drag queen)","C","Daniel Donigan, plus connu sous le nom de scène Milk, est un mannequin et drag queen américain. Il est principalement connu pour avoir participé à la sixième saison de RuPaul's Drag Race et à la troisième saison de RuPaul's Drag Race: All Stars.","Daniel Donigan, plus connu sous le nom de scène Milk, est un mannequin et drag queen américain.","fr:Milk_(drag_queen)","c:b/bf/Rupaul_Dragcon_2018-7_%2840268285440%29.jpg"],["Q116771736",48,"queen","Mistress Isabelle Brooks","C","Mistress Isabelle Brooks est une drag queen texane à l'humour mordant, révélée par la saison 15 de RuPaul's Drag Race.",null,"en:Mistress_Isabelle_Brooks","c:7/74/DragCon_2023_%40_DVSROSS_Photgraphy_-273.jpg"],["Q59363331",49,"queen","Mo Heart","C","Kevin Richardson, plus connu sous le nom de scène Mo Heart, anciennement Monique Heart ou Kutabetch Heart, est une drag queen américaine principalement connue pour sa participation à la dixième saison de RuPaul's Drag Race, la quatrième saison de RuPaul's Drag Race All Stars et la première saison de RuPaul's Drag Race: UK Versus the World.",119,"fr:Mo_Heart","c:2/26/Dragcon3-SUN-28_%2847942903558%29.jpg"],["Q55092372",50,"queen","Monét X Change","R","Kevin Bertin, né le 19 février 1990, plus connu sous le nom de scène Monét X Change, est une personnalité télévisée et drag queen américaine. Elle est principalement connue pour avoir participé à la dixième saison de RuPaul's Drag Race, se plaçant à la sixième place et gagnant le titre de Miss Congeniality.",118,"fr:Monét_X_Change","c:3/3d/Mon%C3%A9t_X_Change_at_Dragcon_by_dvsross.jpg"],["Q56253112",51,"queen","Naomi Smalls","C","Davis Heppenstall, plus connu sous le nom de scène Naomi Smalls, est une drag queen et personnalité télévisée américaine, principalement connue pour sa participation à la huitième saison de RuPaul's Drag Race et à la quatrième saison de RuPaul's Drag Race All Stars.",109,"fr:Naomi_Smalls","c:7/7a/Rupaul_Dragcon_2018-96_%2828203489088%29_%28cropped%29.jpg"],["Q59776942",52,"queen","Nina West","C","Nina West est une drag queen et militante de Columbus (Ohio), Miss Congeniality de la saison 11 de RuPaul's Drag Race.",null,"en:Nina_West","c:a/a1/NINA_PROMO_IMAGE_2020_%28cropped%29.jpg"],["Q123688341",53,"queen","Nymphia Wind","PC","Leo Tsao, plus connu sous le nom de scène Nymphia Wind, est une drag queen américano-taïwanaise, principalement connue pour avoir participé et gagné la seizième saison de RuPaul's Drag Race.",118,"fr:Nymphia_Wind","c:9/97/Nymphia_Wind_at_Taiwan_Presidential_Office_Building_20240515.jpg"],["Q106490072",54,"queen","Olivia Lux","C","Olivia Lux est une drag queen américaine révélée par la saison 13 de RuPaul's Drag Race, réputée pour ses tenues élégantes.",112,"en:Olivia_Lux","c:0/05/RuPaul_DragCon_2022_%2852073487739%29_%28cropped_-_Olivia_Lux%29.jpg"],["Q7130724",55,"queen","Pandora Boxx","C","Pandora Boxx est une drag queen et humoriste américaine de Rochester, révélée par la saison 2 de RuPaul's Drag Race.",null,"en:Pandora_Boxx","c:5/50/DragCon_2023_%40_DVSROSS_Photgraphy_-196.jpg"],["Q20188607",56,"queen","Pearl (drag queen)","C","Matthew James Lent, plus connu sous le nom de scène Pearl Liaison, plus communément Pearl, est une drag queen et artiste américaine. Elle est principalement connu pour avoir participé à la septième saison de RuPaul's Drag Race, où elle finit seconde.",112,"fr:Pearl_(drag_queen)","c:6/64/Rupaul_Dragcon_2018-182_%2842030795432%29.jpg"],["Q16201562",57,"queen","Peppermint","R","Agnes Moore, connue sous son nom de scène Peppermint ou Miss Peppermint, est une actrice, chanteuse, personnalité de la télévision, drag queen et activiste américaine. Elle est surtout connue comme une personnalité importante de la vie nocturne de New York et pour sa participation à la neuvième saison de RuPaul's Drag Race.",119,"fr:Peppermint_(drag_queen)","c:3/3d/Peppermint_at_Rupaul%27s_Dragcon_2017_by_dvsross.jpg"],["Q124260551",58,"queen","Plane Jane","PC","Plane Jane est une drag queen américaine au franc-parler, révélée par la saison 16 de RuPaul's Drag Race.",null,"en:Plane_Jane","c:b/bb/DragCon2024_%40DVSROSS_%28151%29_%28cropped%29.jpg"],["Q124304223",59,"queen","Plasma (drag queen)","C","Plasma est une drag queen, actrice et chanteuse américaine, révélée par la saison 16 de RuPaul's Drag Race.",null,"en:Plasma_(drag_queen)","c:7/70/DragCon2024_%40DVSROSS_%28143%29_Plasma_%28crop%29.jpg"],["Q62140851",60,"queen","Plastique Tiara","R","Plastique Tiara est une drag queen vietnamo-américaine, danseuse et mannequin, révélée par la saison 11 de RuPaul's Drag Race.",115,"en:Plastique_Tiara","c:9/92/Plastique_Tiara_RuPaul%27s_DragCon_LA_2024_%28cropped%29.jpg"],["Q98901190",61,"queen","Priyanka","PC","Priyanka est une drag queen et chanteuse canadienne, gagnante de la première saison de Canada's Drag Race en 2020.",null,"en:Priyanka_(drag_queen)","c:d/de/Priyanka_performing_at_Rockstar_Windsor%2C_2024-11-15_02.jpg"],["Q124304139",62,"queen","Q (drag queen)","C","Q est une drag queen américaine révélée par la saison 16 de RuPaul's Drag Race, connue pour ses créations de mode.",null,"en:Q_(drag_queen)","c:5/5d/DragCon2024_%40DVSROSS_%28137%29_%28cropped2%29.jpg"],["Q64224739",63,"queen","Ra'Jah O'Hara","C","Benni Miller, plus connu sous le nom de scène Ra'Jah O'Hara, est une drag queen américaine principalement connue pour sa participation à la onzième saison de RuPaul's Drag Race, la sixième saison de RuPaul's Drag Race All Stars et la première saison de Canada's Drag Race: Canada vs the World, dont elle est la gagnante.",117,"fr:Ra'Jah_O'Hara","c:3/37/Dragcon2-SAT-68_%2847937164107%29.jpg"],["Q7649891",64,"queen","Raja Gemini","PC","Sutan Ibrahim Karim Amrullah, souvent raccourci en Sutan Amrull, plus connu sous le nom de scène Raja Gemini ou plus simplement Raja, est un maquilleur et drag queen américain, principalement connu pour son travail de la quatrième à la douzième saison de Top Model USA et pour sa participation à la troisième saison de RuPaul's Drag Race et à la septième saison de RuPaul's Drag Race All Stars.",116,"fr:Raja_Gemini","c:c/cb/RuPaul_DragCon_2022_%2852073264823%29.jpg"],["Q94440646",65,"queen","Rock M. Sakura","C","Bryan Bradford, plus connu sous le nom de scène Rock M. Sakura est un chorégraphe et drag queen américain d'origine vietnamienne et philippine principalement connu pour sa participation à la douzième saison de RuPaul's Drag Race.","Bryan Bradford, plus connu sous le nom de scène Rock M.","fr:Rock_M._Sakura","c:f/f0/DragCon_2022-160_%2852075524729%29.jpg"],["Q106465822",66,"queen","Rosé (drag queen)","C","Rosé est une drag queen et chanteuse écossaise installée à New York, révélée par la saison 13 de RuPaul's Drag Race.",null,"en:Rosé_(drag_queen)","c:0/06/Ros%C3%A9_Drag_Queen.jpg"],["Q124260547",67,"queen","Sapphira Cristál","C","Sapphira Cristál est une drag queen américaine et chanteuse lyrique, finaliste et Miss Congeniality de la saison 16 de RuPaul's Drag Race.",115,"en:Sapphira_Cristál","c:e/ed/Dragcon_Friday_2024_-961.jpg"],["Q115689986",68,"queen","Sasha Colby","R","Sasha Kekauoha, plus connue sous le nom de scène Sasha Colby, est une drag queen et reine de beauté américaine, principalement connue pour avoir remporté le concours de beauté Miss Continental et la quinzième saison de RuPaul's Drag Race.",111,"fr:Sasha_Colby","c:7/72/Sasha_Colby_%281%29.jpg"],["Q29913296",69,"queen","Sasha Velour","PC","Alexander « Sasha » Hedges Steinberg, plus connue sous le nom de scène Sasha Velour, est une actrice, directrice artistique et drag queen américaine principalement connue pour sa participation à la neuvième saison de l'émission de téléréalité RuPaul's Drag Race.",112,"fr:Sasha_Velour","c:7/78/Sasha_Velour_%28cropped%29_2.jpg"],["Q7488379",70,"queen","Shangela Laquifa Wadley","R","D.J. Pierce, plus connu sous le nom de scène Shangela Laquifa Wadley, souvent abrégé en Shangela, est une personnalité télévisée et drag queen, principalement connue pour avoir participé à la compétition RuPaul's Drag Race. Elle fut la première candidate éliminée dans la deuxième saison, et fut réintroduite par surprise dans la troisième saison, se plaçant cinquième. Elle revient une fois encore pour la troisième saison de RuPaul's Drag Race: All Stars, où elle se place troisième/quatrième avec BeBe Zahara Benet.","D.J.","fr:Shangela_Laquifa_Wadley","c:e/e1/Shangela_Laquifa_Wadley_at_DragCon%2C_April_2017.png"],["Q16068748",71,"queen","Sharon Needles","PC","Sharon Needles est le nom de scène de Aaron Coady, drag queen et chanteur américain. Coady accède à la notoriété en remportant la quatrième saison de RuPaul's Drag Race en avril 2012.","Sharon Needles est le nom de scène de Aaron Coady, drag queen et chanteur américain.","fr:Sharon_Needles","c:f/f2/Sharon_Needles_Brillobox.jpg"],["Q48688208",72,"queen","Shea Couleé","PC","Shea Couleé est une drag queen principalement connue pour sa participation à la neuvième saison de RuPaul's Drag Race à la cinquième saison de RuPaul's Drag Race: All Stars et à la septième saison de RuPaul's Drag Race: All Stars.",119,"fr:Shea_Couleé","c:c/c1/Shea_Coulee_Baking_with_Bambi_May_2021.png"],["Q63328898",73,"queen","Silky Nutmeg Ganache","C","Silky Nutmeg Ganache est une drag queen américaine haute en couleur, révélée par la saison 11 de RuPaul's Drag Race.",null,"en:Silky_Nutmeg_Ganache","c:b/b3/Dragcon2-SAT-10_%2847937172657%29_%28cropped2%29.jpg"],["Q106040762",74,"queen","Symone (drag queen)","C","Reggie Gavin, plus connu sous le nom de scène Symone, est une drag queen américaine principalement connue pour sa participation à la treizième saison de RuPaul's Drag Race.",113,"fr:Symone","c:a/a1/RuPaul_DragCon_2022_%2852073263726%29.jpg"],["Q105024580",75,"queen","Tayce","E","Tayce Szura-Radix, dit Tayce, est une drag queen galloise, principalement connue pour sa participation à la deuxième saison de RuPaul's Drag Race UK.",116,"fr:Tayce","c:b/b2/Tayce_%28cropped%29.png"],["Q67185184",76,"queen","The Vivienne","E","James Lee Williams, né le 12 avril 1992 à Colwyn Bay et mort le 5 janvier 2025 à Chorlton-by-Backford, plus connu sous le nom de scène The Vivienne, est une drag queen galloise principalement connue pour sa participation à la première saison de RuPaul's Drag Race UK et la septième saison de RuPaul's Drag Race All Stars.",118,"fr:The_Vivienne","c:3/31/RuPaul_with_All_Stars_7_Contestants_at_LA_DragCon_2022_by_dvsross_%28crop_-_The_Vivienne%29.jpg"],["Q49560562",77,"queen","Thorgy Thor","C","Thorgy Thor est une drag queen et musicienne américaine, violoniste, révélée par la saison 8 de RuPaul's Drag Race.",null,"en:Thorgy_Thor","c:3/30/RuPaul_DragCon_2022_%2852073490839%29_%28cropped2%29.jpg"],["Q105024627",78,"queen","Tia Kofi","C","Tia Kofi est une drag queen et chanteuse britannique du sud de Londres, révélée par la deuxième saison de RuPaul's Drag Race UK.",114,"en:Tia_Kofi","c:d/dc/DragCon_2024_%40_DVSROSS_Photgraphy_-28_%28cropped%29.jpg"],["Q58494415",79,"queen","Trinity The Tuck","C","Trinity The Tuck, est une drag queen américaine, principalement connue pour avoir participé à la neuvième saison de RuPaul's Drag Race et à la quatrième et septième saison de RuPaul's Drag Race: All Stars. Pendant la saison 9 de RuPaul's Drag Race, Trinity est connue sous le nom de Trinity Taylor, mais son nom de scène change au début de la saison 4 de RuPaul's Drag Race: All Stars, elle est connue maintenant et seulement sous le nom de Trinity The Tuck.",115,"fr:Trinity_The_Tuck","c:0/0f/Trinity_the_Tuck_Taylor_at_Dragcon_by_dvsross.jpg"],["Q23905339",80,"queen","Trixie Mattel","L","Brian Michael Firkus, plus connu sous le nom de scène Trixie Mattel, est un auteur-compositeur-interprète, comédien, drag queen, auteur, personnalité télévisée et entrepreneur américain principalement connu pour sa participation à la septième saison de RuPaul's Drag Race et à la troisième saison de RuPaul's Drag Race All Stars.",116,"fr:Trixie_Mattel","c:5/5c/Trixie_Mattel_%2849171875887%29_%28cropped%29.jpg"],["Q6142454",81,"queen","Tyra Sanchez","PC","James William Ross, plus connu sous son ancien nom de scène Tyra Sanchez, est une ancienne drag queen et star de télé-réalité américaine. Il est principalement connu pour avoir participé et remporté la seconde édition de la télé-réalité américaine RuPaul's Drag Race en 2010.",112,"fr:Tyra_Sanchez","c:0/08/Tyra_Sanchez_%28cropped%29.jpg"],["Q54948269",82,"queen","Valentina (drag queen)","PC","Valentina Xunaxi Leyva, plus connu sous le nom de Valentina, est une personnalité télévisée et drag queen, principalement connue pour avoir été candidate dans la neuvième saison de RuPaul's Drag Race et la quatrième saison de RuPaul's Drag Race All Stars.",106,"fr:Valentina_(drag_queen)","c:1/19/Valentina_DragCon_cropped.png"],["Q52106707",83,"queen","Vanessa Vanjie Mateo","C","José Cancel, plus connu sous le nom scène Vanessa Vanjie Mateo, parfois raccourci en Miss Vanjie ou Vanjie, est une drag queen américaine principalement connue pour sa participation aux dixième et onzième saisons de RuPaul's Drag Race.",115,"fr:Vanessa_Vanjie_Mateo","c:6/60/Dragcon3-SUN-9_%2847942923151%29.jpg"],["Q20026871",84,"queen","Violet Chachki","R","Jason Dardo, plus connu sous le nom de scène Violet Chachki, est un chanteur, danseur burlesque, mannequin et drag queen américain. Il est principalement connue pour avoir participé à la septième saison de RuPaul's Drag Race, qu'il remporte.",114,"fr:Violet_Chachki","c:b/b6/Violet_Chachki_at_DragCon%2C_April_2017.png"],["Q8003276",85,"queen","Willam Belli","R","Willam Belli est un acteur américain, drag queen, mannequin et chanteur, connu pour son rôle récurrent de femme transgenre Cherry Peck dans la série télévisée Nip/Tuck et pour avoir participé en tant que concurrent à la saison 4 de RuPaul's Drag Race. En plus de sa carrière d'acteur, Belli connut un succès viral sur internet avec des clips de parodies de chansons, formant le trio de drag queens de Los Angeles DWV.",111,"fr:Willam_Belli","c:c/c0/New_York_Pride_50_-_2019-1068_%2848166787216%29.jpg"],["Q111302344",86,"queen","Willow Pill","PC","Willow Patterson, plus connue sous le nom de scène Willow Pill, est une drag queen américaine principalement connue pour sa participation à la quatorzième saison de RuPaul's Drag Race.",115,"fr:Willow_Pill","c:f/fa/RuPaul_DragCon_2022_%2852073264228%29.jpg"],["Q64009078",87,"queen","Yvie Oddly","PC","Jovan Bridges, plus connu sous le nom de scène Yvie Oddly, est un artiste, styliste et une drag queen américaine qui connaît le succès en 2019 après avoir participé à la onzième saison de l'émission RuPaul's Drag Race, dont elle ressort vainqueur.",116,"fr:Yvie_Oddly","c:d/d9/Dragcon-25_%2847937194866%29.jpg"],["Q807829",88,"icone","Barbette","C","Vander Clyde Broadway, nom de scène Barbette, est un travesti fil-de-fériste et trapéziste américain. Barbette a atteint une grande popularité à travers les États-Unis, mais c'est en Europe, et plus particulièrement à Paris, qu'il a connu sa plus grande renommée dans les années 1920 et 1930.","Vander Clyde Broadway, nom de scène Barbette, est un travesti fil-de-fériste et trapéziste américain.","fr:Barbette_(artiste)","c:3/3d/Barbette_%28Trapezk%C3%BCnstler%29.jpg"],["Q4898387",89,"icone","Bette Bourne","C","Bette Bourne (1939-2024) était un acteur, drag queen et militant britannique, pionnier du théâtre queer avec la troupe Bloolips.",111,"en:Bette_Bourne","c:d/d6/Bette_Bourne.jpg"],["Q550202",90,"icone","Candy Darling","E","Candy Darling est une actrice américaine. « Superstar » de la Factory d’Andy Warhol, figure du New York underground de la fin des années 60 et du début des années 70, elle est une icône trans.","Candy Darling est une actrice américaine.","fr:Candy_Darling","c:b/bd/Candy_Darling_in_Silent_Night%2C_Bloody_Night.png"],["Q51852840",91,"icone","Crystal LaBeija","C","Crystal LaBeija, née dans les années 1930 et morte dans les années 1990 est une artiste afro-américaine, trans, drag queen, fondatrice de la House of LaBeija en 1968. Cette House est souvent citée comme étant la première de la culture ballroom. Elle est considérée comme étant mère de substitution de plusieurs jeunes LGBTQ rejetés de chez eux et sans abri.",116,"fr:Crystal_LaBeija","https://upload.wikimedia.org/wikipedia/en/thumb/9/98/Crystal_LaBeija.jpg/330px-Crystal_LaBeija.jpg"],["Q1158334",92,"icone","Dame Edna Everage","L","Dame Edna Everage est un personnage imaginaire incarné par l'humoriste australien Barry Humphries. Elle est facilement reconnaissable à ses cheveux couleur lilas et à ses lunettes.","Dame Edna Everage est un personnage imaginaire incarné par l'humoriste australien Barry Humphries.","fr:Dame_Edna_Everage","c:f/f7/Dame_Edna_%286959716988%29.jpg"],["Q1851318",93,"icone","Danny La Rue","R","Danny La Rue, né Daniel Patrick Carroll le 26 juillet 1927 et mort le 31 mai 2009, est un artiste britannique, connu pour ses spectacles de chant et de travestissement.",116,"fr:Danny_La_Rue","c:7/70/Danny_La_Rue_1975.jpg"],["Q357786",94,"icone","Divine","M","Harris Glenn Milstead, mieux connu sous le nom de drag queen Divine, est un acteur et chanteur américain, célèbre, notamment, pour avoir joué à six reprises sous la direction de John Waters. Il semble que son nom de drag soit une référence au personnage de Divine dans le roman Notre-Dame des Fleurs de Jean Genet.",114,"fr:Divine_(artiste)","c:a/a2/Pink_Flamingos_-_Divine.jpg"],["Q5297781",95,"icone","Dorian Corey","PC","Dorian Corey (1937-1993) était une drag queen et créatrice de mode américaine, figure des bals de Harlem immortalisée dans le documentaire Paris Is Burning.",104,"en:Dorian_Corey","https://upload.wikimedia.org/wikipedia/en/thumb/4/45/Dorian_Corey.jpg/330px-Dorian_Corey.jpg"],["Q112967616",96,"icone","Drag Race Belgique","C","Drag Race Belgique est une émission de télé-réalité de compétition belge dérivée de RuPaul's Drag Race, créée en 2023 par Nick Murray et RuPaul et produite par la RTBF et World of Wonder pour Auvio, Tipik et WOW Presents Plus.",117,"fr:Drag_Race_Belgique","c:2/24/DRAGRACE_VECTO_01_2D.png"],["Q1759260",97,"icone","Extravagances","M","Extravagances ou À Wong Foo, merci pour tout Julie Newmar au Québec est un film américain de Beeban Kidron sorti en 1995.",115,"fr:Extravagances","https://upload.wikimedia.org/wikipedia/en/thumb/e/e9/Towongfoo.jpg/330px-Towongfoo.jpg"],["Q5697094",98,"icone","Hedda Lettuce","C","Hedda Lettuce est une drag queen, comédienne et chanteuse new-yorkaise, figure de la scène drag de Manhattan depuis les années 1990.",115,"en:Hedda_Lettuce","c:e/ed/HeddaLettuce.jpg"],["Q5767087",99,"icone","Hinge and Bracket","PC","Hinge and Bracket était un duo comique britannique de deux vieilles dames chanteuses, interprétées par les travestis George Logan et Patrick Fyffe.",116,"en:Hinge_and_Bracket","https://upload.wikimedia.org/wikipedia/en/thumb/c/c7/Hinge_and_Bracket.jpg/330px-Hinge_and_Bracket.jpg"],["Q6116219",100,"icone","Jackie Beat","C","Jackie Beat est une drag queen, chanteuse et scénariste américaine, figure de la scène drag de Los Angeles.",null,"en:Jackie_Beat","c:d/d5/Jackie_beat.jpg"],["Q3249409",101,"icone","John Epperson","C","John Epperson est un artiste américain, créateur du personnage drag Lypsinka, célèbre pour ses spectacles de playback millimétrés.",108,"en:John_Epperson","c:3/3d/Lypsinka_1_by_David_Shankbone.jpg"],["Q1711980",102,"icone","Julian Eltinge","C","Julian Eltinge, né le 14 mai 1881 à Newtonville et mort le 7 mars 1941 à New-York, est un acteur américain de théâtre et de cinéma, interprétant des rôles féminins et considéré comme un des premiers Drag queen du cinéma. Il est un des acteurs les mieux payés de son époque.",117,"fr:Julian_Eltinge","c:b/bd/Julian_Eltinge_001.JPG"],["Q6395755",103,"icone","Kevin Aviance","C","Kevin Aviance est une drag queen et musicien dance new-yorkais, icône des clubs gays des années 1990.",null,"en:Kevin_Aviance","c:c/c5/Fierce_Hiro_at_the_Maritime_Hotel_20070910.10D.45792_SML_%281389640840%29.jpg"],["Q6470006",104,"icone","Lady Bunny","PC","Lady Bunny, connue d’abord sous le nom de « Bunny Hickory Dickory Dock », parfois surnommée « The Lady Bunny », est une drag queen, actrice, et chanteuse. Née Jon Ingle le 14 août 1962 à Wilmington, Lady Bunny est une icône connue de la communauté drag queen à New York.",119,"fr:Lady_Bunny","c:b/b3/Lady_Bunny_2001.jpg"],["Q456460",105,"icone","Miss Coco Peru","PC","Miss Coco Peru est le personnage drag de l'acteur Clinton Leupp, connue pour ses monologues et son rôle dans le film Trick (1999).",116,"en:Miss_Coco_Peru","c:1/17/Coco_Peru_by_David_Shankbone.jpg"],["Q1416917",106,"icone","Paul O'Grady","E","Paul O'Grady (1955-2023) était un humoriste et animateur anglais, célèbre pour son personnage drag Lily Savage.",null,"en:Paul_O'Grady","c:8/80/Paul_O%27Grady%2C_April_2009_cropped.jpg"],["Q7166361",107,"icone","Pepper LaBeija","PC","Pepper LaBeija (1948-2003) était une drag queen et créatrice de mode américaine, surnommée « la dernière reine des bals drag de Harlem ».",114,"en:Pepper_LaBeija","c:d/d6/Pepper_LaBeija_Illustration.png"],["Q221249",108,"icone","Tootsie","L","Tootsie est un film américain réalisé par Sydney Pollack, sorti en 1982 avec Dustin Hoffman dans le rôle principal.",null,"fr:Tootsie","c:8/81/Tootsie_-_plak%C3%A1t_Jan_Sarkandr_Tom%C3%A1nek.jpg"],["Q7920612",109,"icone","Venus Xtravaganza","R","Venus Xtravaganza, née le 5 mai 1965 à Jersey City et morte le 21 décembre 1988 à New York, est une performeuse transgenre américaine. Elle a attiré l'attention à la suite de son apparition dans le film documentaire de Jennie Livingston, Paris Is Burning, en 1990, qui raconte sa vie de femme trans.",111,"fr:Venus_Xtravaganza","https://upload.wikimedia.org/wikipedia/en/thumb/a/a4/Venus_Xtravaganza.jpg/330px-Venus_Xtravaganza.jpg"],["Q718111",110,"icone","Willi Ninja","PC","Willi Ninja, né William Roscoe Leake le 12 avril 1961 à New York et mort le 2 septembre 2006 dans la même ville, est un danseur, chorégraphe américain, autodidacte.",119,"fr:Willi_Ninja","c:f/f6/Willi_Ninga_NYC.jpg"],["Q57313354",111,"fr","Cookie Kunty","C","Cookie Kunty, civilement connue sous le nom de Romain Eck, est une drag queen franco-canadienne.",null,"fr:Cookie_Kunty","c:5/51/Dragathon_4-2019_03.jpg"],["Q121883429",112,"fr","Elips","C","Elips, nom de drag d'Ely Méchain, est une artiste drag queer française. Elips est connue pour sa participation à la saison 1 de Drag Race France et à la saison 1 de Drag Race France All Stars.","Elips, nom de drag d'Ely Méchain, est une artiste drag queer française.","fr:Elips_(drag_queer)","c:f/fd/Elips_durant_la_Pride_Night_au_Rockstore_de_Montpellier_5.png"],["Q57313365",113,"fr","Keiona","C","Keiona est le nom de scène d'une drag queen, danseuse de vogue et performeuse de la scène ballroom française, née le 4 janvier 1992 à Paris.",118,"fr:Keiona","c:d/df/Dragcon-uk-2024-draglicious-dia-1-keiona_%28cropped%29.png"],["Q123485167",114,"fr","Kitty Space","C","Kiara Denis, plus connue sous le nom Kitty Space, est une drag queen française célèbre notamment pour sa participation à la saison 2 de Drag Race France et comme membre du collectif Rice Queers.",118,"fr:Kitty_Space","c:8/87/Kitty_Space_2_%28cropped%29.jpg"],["Q120135329",115,"fr","La Big Bertha","C","La Big Bertha, nom de scène de Loïc Assemat, né le 19 mai 1985 à Castres, en Occitanie, est une drag queen, comédienne et chanteuse française. Il est également connu pour sa participation à la saison 1 de Drag Race France et à la saison 1 de Drag Race France All Stars.",118,"fr:La_Big_Bertha","c:a/a5/La_Big_Bertha_lors_du_Rosa_Festival_2024.jpg"],["Q117353497",116,"fr","La Grande Dame","C","La Grande Dame, née le 19 mars 1999 à Nice, est une drag queen française et un mannequin, également auteur-compositeur-interprète en tant que Yann.",99,"fr:La_Grande_Dame","c:1/1e/Yan_Pride_Paris_2026.jpg"],["Q124375659",117,"fr","Le Filip","C","Le Filip est un artiste drag queen croate né à Zagreb. Spécialisé dans le stand-up, il est sacré reine lors de la saison 3 de Drag Race France.","Le Filip est un artiste drag queen croate né à Zagreb.","fr:Le_Filip","c:5/50/Le_Filip_-_Pride_de_Paris_2026.jpg"],["Q118323089",118,"fr","Lolita Banana","C","Esteban Inzúa, plus connu sous le nom de scène Lolita Banana, est une drag queen mexicaine principalement connue pour sa participation à la première saison de Drag Race France et comme présentatrice de Drag Race México.",117,"fr:Lolita_Banana","c:6/65/DragCon_2023_%40_DVSROSS_Photgraphy_-75_%28cropped%29.jpg"],["Q120187006",119,"fr","Lova Ladiva","C","Sébastien Ducellier, plus connu sous le nom de scène Lova Ladiva, est un chorégraphe et drag queen française principalement connu pour sa participation à la première saison de Drag Race France.",108,"fr:Lova_Ladiva","c:2/29/Drag_Race_Viewing_Party_Toulouse_-_2023-06-30_19-20-47_-_Lova_Ladiva_-_1683.jpg"],["Q113090385",120,"fr","Minima Gesté","C","Minima Gesté, de son vrai nom Arthur Raynaud, né le 12 juillet 1990 à Toulouse, est une drag queen française.",null,"fr:Minima_Gesté","c:0/04/Minima_Gest%C3%A9.jpg"],["Q125974736",121,"fr","Misty Phoenix","C","Misty Phoenix est une drag queen française connue pour avoir remporté la saison 3 de Drag me Up et pour sa participation à la saison 3 de Drag Race France et à la saison 1 de Drag Race France All Stars.",106,"fr:Misty_Phoenix","c:2/22/Misty_Phoenix_-_Drag_Race_France_All_Stars_cast.jpg"],["Q95478879",122,"fr","Nicky Doll","PC","Karl Sanchez, plus connu sous le nom de scène Nicky Doll, est une drag queen française exerçant principalement aux États-Unis. Elle est connue pour sa participation à la douzième saison de RuPaul's Drag Race, comme présentatrice de Drag Race France et pour avoir participé à la Cérémonie d'ouverture des Jeux olympiques 2024.",114,"fr:Nicky_Doll","c:4/43/Nicky_Doll_in_2022_%28cropped%29.jpg"],["Q123485128",123,"fr","Rose et Punani","C","Rose et Punani est un duo de drag queen françaises qui a participé à la saison 2 de Drag Race France.",null,"fr:Rose_et_Punani","c:8/89/Rose_et_Punani.jpg"],["Q113495068",124,"fr","Soa de Muse","C","Soa de Muse, née le 31 janvier 1989 à Villepinte, est une drag queen française.",null,"fr:Soa_de_Muse","c:0/07/Soa_de_Muse_%28Mus%C3%A9e_du_quai_Branly%2C_Paris%29_%28cropped%29.jpg"],["Q123717274",125,"queen","Max (drag queen)","C","Max est une drag queen américaine au style vintage et raffiné, révélée par la septième saison de RuPaul's Drag Race.",null,"en:Max_(drag_queen)",""],["Q20998474",126,"icone","Edna Turnblad","C","Edna Turnblad est la mère au grand cœur de Tracy dans Hairspray, traditionnellement jouée par un homme travesti : Divine dans le film de 1988, puis John Travolta en 2007.",113,"en:Edna_Turnblad",""],["Q7915977",127,"icone","Varla Jean Merman","C","Varla Jean Merman est le personnage drag de l'acteur et chanteur américain Jeffery Roberson, connue pour ses spectacles comiques et musicaux.",108,"en:Varla_Jean_Merman",""],["Q122661731",128,"fr","Mademoiselle Boop","C","Mademoiselle Boop, aussi connue au quotidien sous le nom de Renaud Delauvaux, né en 1985 à Dinant, est une drag queen belge, fondatrice et propriétaire du Cabaret Mademoiselle à Bruxelles.",117,"fr:Mademoiselle_Boop",""],["Q141861557",129,"fr","Matthieu Barbin","C","Matthieu Barbin, est un artiste et un performeur français. Il est notamment connu pour avoir participé à la deuxième saison de Drag Race France sous le nom de Sara Forever.","Matthieu Barbin, est un artiste et un performeur français.","fr:Matthieu_Barbin",""]]]);